  <script>
    const samples={
      '7d':{spend:'৳১২,৪৫০',revenue:'৳৪৭,৬০০',leads:'৮৪',roas:'৩.৮২×',income:[138,110,121,86,98,54,68],cost:[184,178,187,169,175,163,171],labels:['Oct 23','Oct 24','Oct 25','Oct 26','Oct 27','Oct 28','Oct 29']},
      '30d':{spend:'৳৪৮,৫০০',revenue:'৳১,৭৬,২০০',leads:'৩৪৮',roas:'৩.৬৪×',income:[150,137,119,127,99,86,68],cost:[188,180,176,183,169,164,171],labels:['Oct 1','Oct 5','Oct 10','Oct 15','Oct 20','Oct 25','Oct 29']},
      '90d':{spend:'৳১,৩৯,৮০০',revenue:'৳৪,৯০,৪০০',leads:'১,০২৪',roas:'৩.৫১×',income:[164,142,153,112,103,80,58],cost:[192,184,182,176,169,174,164],labels:['Aug 1','Aug 15','Sep 1','Sep 15','Oct 1','Oct 15','Oct 29']}
    };
    const xs=[48,156,264,372,480,588,700];
    function linePath(values){return values.map((v,i)=>`${i?'L':'M'}${xs[i]} ${v}`).join(' ')}
    function updateRange(range){
      const data=samples[range];
      document.getElementById('spendValue').textContent=data.spend;
      document.getElementById('revenueValue').textContent=data.revenue;
      document.getElementById('leadsValue').textContent=data.leads;
      document.getElementById('roasValue').textContent=data.roas;
      const income=linePath(data.income),cost=linePath(data.cost);
      document.getElementById('incomeLine').setAttribute('d',income);
      document.getElementById('incomeFill').setAttribute('d',`M${xs[0]} 205 ${data.income.map((v,i)=>`L${xs[i]} ${v}`).join(' ')} L${xs[6]} 205 Z`);
      document.getElementById('spendLine').setAttribute('d',cost);
      document.getElementById('chartDots').innerHTML=data.income.map((v,i)=>`<circle class="chart-dot-a" cx="${xs[i]}" cy="${v}" r="4"/>`).join('')+data.cost.map((v,i)=>`<circle class="chart-dot-b" cx="${xs[i]}" cy="${v}" r="3"/>`).join('');
      document.getElementById('chartLabels').innerHTML=data.labels.map((label,i)=>`<text x="${xs[i]}" y="226" text-anchor="middle">${label}</text>`).join('');
      document.querySelectorAll('[data-range]').forEach(button=>button.classList.toggle('active',button.dataset.range===range));
    }
    document.querySelectorAll('[data-range]').forEach(button=>button.addEventListener('click',()=>updateRange(button.dataset.range)));
    const csv='Campaign,Platform,Status,Spend,Leads,Cost per Lead,ROAS\nLead Generation - Core,Meta Ads,Active,5200,38,137,4.1x\nSearch - Service Keywords,Google Ads,Active,4600,27,170,3.5x\nRetargeting - Website Visitors,Meta Ads,Paused,2650,19,140,3.8x';
    function exportCsv(){const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='marketing-dashboard-demo.csv';link.click();URL.revokeObjectURL(link.href)}
    document.getElementById('exportCsv').addEventListener('click',exportCsv);
    document.getElementById('exportTable').addEventListener('click',exportCsv);
  </script>
